let data=(typeof structuredClone === "function") ? structuredClone(D) : JSON.parse(JSON.stringify(D));
let live=false, loadErrors=[];
const state={page:1,pageSize:10,query:"",filters:{},sort:"",dir:"asc"};
function n(v){return Number(v||0)}
function text(v){return v==null?"":String(v)}
function statusLabel(v){return text(v).replaceAll("_"," ").replace(/\b\w/g,c=>c.toUpperCase())}
function fullName(f){if(!f)return "Unknown"; return f.name || [f.first_name,f.middle_name,f.last_name].filter(Boolean).join(" ")}
function initials(v){return text(v).split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join("").toUpperCase()||"FA"}
function byId(arr,id){return (arr||[]).find(x=>String(x.id)===String(id))}
function faculty(id){return byId(data.faculty,id)}
function subject(id){return byId(data.subjects,id)}
function cls(id){return byId(data.classes,id)}
function program(id){return byId(data.programs,id)}
function ay(id){return byId(data.academicYears,id)}
function departmentFor(f){return f?.department || f?.departments?.name || byId(data.departments,f?.department_id)?.name || "Unassigned"}
function workloadFor(fid){let w=(data.workload||[]).find(x=>String(x.faculty_id)===String(fid)); if(w)return {...w,total:n(w.lecture_hours)+n(w.practical_hours)+n(w.administrative_hours)}; const rows=(data.classAssignments||[]).filter(x=>String(x.faculty_id)===String(fid)&&x.status!=="INACTIVE"); return {faculty_id:fid,lecture_hours:rows.reduce((s,x)=>s+n(x.weekly_lectures),0),practical_hours:rows.reduce((s,x)=>s+n(x.practical_hours),0),administrative_hours:0,total:rows.reduce((s,x)=>s+n(x.weekly_lectures)+n(x.practical_hours),0)} }
function workloadStatus(total){return total<10?"Low":total<=18?"Normal":total<=24?"High":"Overloaded"}
function attendanceRate(fid){const f=faculty(fid); if(f?.attendance!=null)return n(f.attendance); const rows=(data.attendance||[]).filter(x=>String(x.faculty_id)===String(fid)); if(!rows.length)return 0; const score=rows.reduce((s,x)=>s+(x.status==="PRESENT"?1:x.status==="HALF_DAY"?.5:x.status==="OFFICIAL_DUTY"?1:0),0); return Math.round(score/rows.length*100)}
function badge(v){const label=statusLabel(v);const key=label.toLowerCase().replace(/\s+/g,"-");return `<span class="badge badge-${key}"><span></span>${escapeHtml(label)}</span>`}
function sourcePill(){return `<span class="faculty-source-pill ${live?"":"demo"}"><span></span>${live?"Supabase connected":"Demo fallback"}</span>`}
function head(title,desc,actions=""){return `<div class="page-heading"><div><span class="eyebrow">FACULTY ADMIN · CAMPUSX</span><h1>${escapeHtml(title)}</h1><p>${escapeHtml(desc)}</p></div><div class="page-actions">${sourcePill()}${actions}</div></div>`}
function notice(){ if(!loadErrors.length)return ""; return `<div class="dashboard-notice"><span>${icon("warning")}</span><div><strong>Live data partially unavailable</strong><p>CampusX is showing safe demo fallback data for unavailable Faculty Operations tables. Apply migration 012 and configure the Supabase client to enable live operations.</p></div></div>`; }
function actionBtn(label,attrs="",kind="secondary"){return `<button class="btn btn-${kind}" type="button" ${attrs}>${escapeHtml(label)}</button>`}
function csv(rows,columns,filename){const esc=v=>`"${text(v).replace(/"/g,'""')}"`; const out=[columns.map(c=>c.label),...rows.map(r=>columns.map(c=>typeof c.value==="function"?c.value(r):r[c.value]))].map(row=>row.map(esc).join(",")).join("\n"); const blob=new Blob(["\ufeff"+out],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);showToast("CSV export prepared.","success")}
function stat(label,value,detail=""){return `<article class="faculty-kpi"><strong>${escapeHtml(value)}</strong><span>${escapeHtml(label)}</span>${detail?`<small>${escapeHtml(detail)}</small>`:""}</article>`}
function escapeAttr(v){return escapeHtml(v).replace(/`/g,"&#96;")}

function normalizeLive(raw){
 const out={...data};
 if(raw.faculty?.length){
   const liveFaculty=raw.faculty.map(f=>({...f,name:fullName(f),department:f.departments?.name||"Unassigned",attendance:f.attendance??null}));
   out.faculty=liveFaculty.length>=5 ? liveFaculty : [...liveFaculty,...D.faculty.filter(d=>!liveFaculty.some(l=>l.faculty_id===d.faculty_id))];
 }
 for(const k of ["departments","programs","subjects","classes","academicYears"]){
   if(raw[k]?.length){
     const demo=D[k]||[]; const liveRows=raw[k];
     out[k]=liveRows.length>=5 ? liveRows : [...liveRows,...demo.filter(d=>!liveRows.some(l=>(l.id&&l.id===d.id)||(l.code&&d.code&&l.code===d.code)))];
   }
 }
 for(const k of ["subjectAssignments","classAssignments","workload","attendance","leaveRequests","requests","resources","responsibilities","activities","schedule","documents"]) if(raw[k]?.length) out[k]=raw[k];
 return out;
}
async function load(){
 if(service){const res=await service.bootstrap(); live=Boolean(res.live && res.data?.faculty?.length); loadErrors=res.errors||[]; data=normalizeLive(res.data||{});} render();
}

function optionList(values,current=""){return values.map(v=>`<option value="${escapeAttr(v)}" ${String(v)===String(current)?"selected":""}>${escapeHtml(statusLabel(v))}</option>`).join("")}
function smartTable(cfg){
 const tableId=`ft-${Math.random().toString(36).slice(2,8)}`; let local={page:1,pageSize:cfg.pageSize||10,query:"",filters:{},sort:cfg.sortDefault||"",dir:"asc"};
 const filters=cfg.filters||[]; const sortables=cfg.columns.filter(c=>c.sortKey);
 const shell=document.createElement("section"); shell.className="card faculty-table-card"; shell.dataset.facultyTable=tableId;
 shell.innerHTML=`<div class="faculty-toolbar"><label class="student-search">${icon("search")}<input type="search" data-q placeholder="${escapeAttr(cfg.searchPlaceholder||"Search...")}" aria-label="Search"></label><div class="faculty-filter-group">${filters.map(f=>`<select data-filter="${escapeAttr(f.key)}" aria-label="${escapeAttr(f.label)}"><option value="">All ${escapeHtml(f.label)}</option>${f.options.map(o=>`<option value="${escapeAttr(o.value??o)}">${escapeHtml(o.label??statusLabel(o))}</option>`).join("")}</select>`).join("")}<select data-sort class="faculty-sort-select" aria-label="Sort records"><option value="">Sort by</option>${sortables.map(c=>`<option value="${escapeAttr(c.sortKey)}">${escapeHtml(c.label)}</option>`).join("")}</select><select data-dir aria-label="Sort direction"><option value="asc">Ascending</option><option value="desc">Descending</option></select>${cfg.export!==false?`<button class="btn btn-secondary" type="button" data-export>${icon("download")} Export</button>`:""}</div></div><div data-table-body></div><div class="faculty-table-meta"><span data-count></span><div class="faculty-pagination" data-pages></div><label>Rows <select data-size><option>10</option><option>25</option><option>50</option><option>100</option></select></label></div>`;
 function processed(){let rows=[...(cfg.rows||[])];const q=local.query.trim().toLowerCase();if(q)rows=rows.filter(r=>(cfg.searchFields||[]).some(k=>text(typeof k==="function"?k(r):r[k]).toLowerCase().includes(q)));filters.forEach(f=>{const v=local.filters[f.key];if(v)rows=rows.filter(r=>String(f.value?f.value(r):r[f.key])===String(v));});if(local.sort){const col=sortables.find(c=>c.sortKey===local.sort);if(col){const get=col.sortValue||((r)=>r[col.sortKey]);rows.sort((a,b)=>{let A=get(a),B=get(b);if(typeof A==="number"||typeof B==="number")return (n(A)-n(B))*(local.dir==="desc"?-1:1);return text(A).localeCompare(text(B),undefined,{numeric:true,sensitivity:"base"})*(local.dir==="desc"?-1:1)});}}return rows;}
 function refresh(){const rows=processed();const pages=Math.max(1,Math.ceil(rows.length/local.pageSize));local.page=Math.min(local.page,pages);const start=(local.page-1)*local.pageSize;const view=rows.slice(start,start+local.pageSize);const body=shell.querySelector("[data-table-body]");body.innerHTML=view.length?`<div class="table-wrap"><table><thead><tr>${cfg.columns.map(c=>`<th class="${c.align||""}">${escapeHtml(c.label)}</th>`).join("")}</tr></thead><tbody>${view.map(r=>`<tr>${cfg.columns.map(c=>`<td class="${c.align||""}">${c.render?c.render(r):escapeHtml(r[c.key]??"")}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`:`<div class="faculty-state"><span class="state-icon">${icon("document")}</span><h3>No records found</h3><p>No records match the current search and filters.</p><button class="btn btn-secondary" type="button" data-clear>Clear filters</button></div>`; shell.querySelector("[data-count]").textContent=rows.length?`Showing ${start+1}–${Math.min(start+local.pageSize,rows.length)} of ${rows.length}`:"0 records";const p=shell.querySelector("[data-pages]");p.innerHTML=`<button class="faculty-page-button" data-page="prev" ${local.page===1?"disabled":""}>‹</button>${Array.from({length:Math.min(5,pages)},(_,i)=>{let num=pages<=5?i+1:Math.max(1,Math.min(local.page-2,pages-4))+i;return `<button class="faculty-page-button ${num===local.page?"active":""}" data-page="${num}">${num}</button>`}).join("")}<button class="faculty-page-button" data-page="next" ${local.page===pages?"disabled":""}>›</button>`;}
 shell.addEventListener("input",e=>{if(e.target.matches("[data-q]")){local.query=e.target.value;local.page=1;refresh();}});shell.addEventListener("change",e=>{if(e.target.matches("[data-filter]")){local.filters[e.target.dataset.filter]=e.target.value;local.page=1;refresh();}if(e.target.matches("[data-sort]")){local.sort=e.target.value;local.page=1;refresh();}if(e.target.matches("[data-dir]")){local.dir=e.target.value;local.page=1;refresh();}if(e.target.matches("[data-size]")){local.pageSize=Number(e.target.value);local.page=1;refresh();}});shell.addEventListener("click",e=>{const pg=e.target.closest("[data-page]");if(pg){const rows=processed(),pages=Math.max(1,Math.ceil(rows.length/local.pageSize));local.page=pg.dataset.page==="prev"?Math.max(1,local.page-1):pg.dataset.page==="next"?Math.min(pages,local.page+1):Number(pg.dataset.page);refresh();return;}if(e.target.closest("[data-clear]")){local={...local,page:1,query:"",filters:{},sort:"",dir:"asc"};shell.querySelectorAll("input,select").forEach(x=>{if(x.matches("[data-size]"))x.value=String(local.pageSize);else if(x.matches("[data-dir]"))x.value="asc";else x.value=""});refresh();return;}if(e.target.closest("[data-export]")){csv(processed(),cfg.columns.filter(c=>c.export!==false).map(c=>({label:c.label,value:c.exportValue||c.key||((r)=>text(r[c.key]))})),cfg.filename||"campusx-faculty-export.csv");return;}const act=e.target.closest("[data-row-action]");if(act&&cfg.onAction){const row=(cfg.rows||[]).find(r=>String(r.id)===String(act.dataset.rowId));cfg.onAction(act.dataset.rowAction,row,refresh);}});refresh();return shell;
}
function mountTable(cfg){const host=document.querySelector(cfg.host||"#module-table");if(host){host.innerHTML="";host.appendChild(smartTable(cfg));}}
function facultyNameCell(f){return `<div class="faculty-name-cell"><span class="faculty-avatar">${initials(fullName(f))}</span><span><strong>${escapeHtml(fullName(f))}</strong><small>${escapeHtml(f.email||"")}</small></span></div>`}
function rowActions(id,actions){return `<div class="faculty-action-menu">${actions.map(a=>`<button class="table-action ${a.secondary?"secondary":""}" type="button" data-row-action="${escapeAttr(a.key)}" data-row-id="${escapeAttr(id)}">${escapeHtml(a.label)}</button>`).join("")}</div>`}
function simpleModal(title,html,buttons=""){const root=document.querySelector("#dashboard-modal-root");if(!root)return;root.innerHTML=`<div class="modal-backdrop" data-rich-backdrop><section class="dashboard-modal faculty-rich-modal" role="dialog" aria-modal="true" aria-labelledby="rich-title"><button class="icon-button modal-close" type="button" data-rich-close aria-label="Close">${icon("close")}</button><h2 id="rich-title">${escapeHtml(title)}</h2>${html}<div class="modal-actions">${buttons||`<button class="btn btn-secondary" type="button" data-rich-close>Close</button>`}</div></section></div>`;root.querySelectorAll("[data-rich-close]").forEach(b=>b.addEventListener("click",()=>root.innerHTML=""));root.querySelector("[data-rich-backdrop]")?.addEventListener("click",e=>{if(e.target===e.currentTarget)root.innerHTML=""});}
function formModal(title,fields,onSubmit,submitLabel="Save") {const formId="fm-"+Math.random().toString(36).slice(2);const html=`<form id="${formId}" class="faculty-modal-form">${fields.join("")}<div class="faculty-form-error" data-form-error hidden></div></form>`;simpleModal(title,html,`<button class="btn btn-secondary" type="button" data-rich-close>Cancel</button><button class="btn btn-primary" type="submit" form="${formId}">${escapeHtml(submitLabel)}</button>`);const form=document.getElementById(formId);form?.addEventListener("submit",async e=>{e.preventDefault();const err=form.querySelector("[data-form-error]");err.hidden=true;const vals=Object.fromEntries(new FormData(form).entries());try{const res=await onSubmit(vals);if(res?.ok===false)throw new Error(res.error?.message||"Unable to save record.");document.querySelector("#dashboard-modal-root").innerHTML="";showToast("Saved successfully.","success");await load();}catch(ex){err.textContent=ex.message||String(ex);err.hidden=false;}})}
function selectField(name,label,rows,value=(r)=>r.id,textFn=(r)=>r.name,required=true){return `<label>${escapeHtml(label)}<select name="${name}" ${required?"required":""}><option value="">Select ${escapeHtml(label)}</option>${rows.map(r=>`<option value="${escapeAttr(value(r))}">${escapeHtml(textFn(r))}</option>`).join("")}</select></label>`}
function inputField(name,label,type="text",attrs=""){return `<label>${escapeHtml(label)}<input name="${name}" type="${type}" ${attrs}></label>`}
function textareaField(name,label){return `<label class="full">${escapeHtml(label)}<textarea name="${name}"></textarea></label>`}
function liveOrDemo(action,payload){if(live&&service&&typeof service[action]==="function")return service[action](payload);return Promise.resolve({ok:true,data:{id:"demo-"+Date.now(),...payload},demo:true});}

