 main.innerHTML=`${head("Faculty Profile","Operational profile for an existing faculty master record.",`<a class="btn btn-secondary" href="faculty.html">Back to Directory</a>`)}<section class="faculty-profile-head"><span class="faculty-profile-avatar">${initials(fullName(f))}</span><div><h1>${escapeHtml(fullName(f))}</h1><p>${escapeHtml(f.faculty_id||"")} · ${escapeHtml(departmentFor(f))} · ${escapeHtml(f.designation||"")}</p></div>${badge(f.status)}</section><div class="faculty-master-owner">${icon("info")} Protected master fields are read-only here and managed by Institute Administration.</div><div class="faculty-tabs" role="tablist">${tabs.map((t,i)=>`<button type="button" class="${i===0?"active":""}" data-profile-tab="${i}">${escapeHtml(t)}</button>`).join("")}</div><section class="card" data-profile-panel></section>`;
