function tableMini(rows,heads,rowFn){return rows.length?`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${escapeHtml(h)}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${rowFn(r).map(v=>`<td>${escapeHtml(v??"—")}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`:`<div class="faculty-state"><p>No records are available for this profile section.</p></div>`}
function dateOnly(v){return text(v).slice(0,10)}
function dayName(n){return ["","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"][Number(n)]||"—"}

