function detectConflicts(rows){const issues=[];for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++){const a=rows[i],b=rows[j];if(String(a.day_of_week)!==String(b.day_of_week)||String(a.schedule_date||"")!==String(b.schedule_date||""))continue;const overlap=text(a.start_time)<text(b.end_time)&&text(b.start_time)<text(a.end_time);if(!overlap)continue;if(String(a.faculty_id)===String(b.faculty_id))issues.push({type:"Faculty",a,b,text:`${fullName(faculty(a.faculty_id))} has overlapping schedule entries.`});if(a.room&&b.room&&a.room===b.room)issues.push({type:"Room",a,b,text:`Room ${a.room} is allocated twice.`});if(a.class_id&&b.class_id&&String(a.class_id)===String(b.class_id))issues.push({type:"Class",a,b,text:`${cls(a.class_id)?.name||"Class"} has overlapping lectures.`});}return issues;}
