function renderActivities(){const rows=data.activities.map(r=>({...r,facultyName:fullName(faculty(r.faculty_id)||r.faculty)}));main.innerHTML=`${head("Faculty Activities","Monitor workshops, conferences, research, FDPs and industry interactions.",actionBtn("Add Activity","data-add-activity","primary"))}<div id="module-table"></div>`;mountTable({rows,searchFields:["facultyName","category","title","organizer"],filters:[{key:"status",label:"Statuses",options:["PLANNED","ONGOING","COMPLETED","CANCELLED"]}],columns:[{label:"Faculty",key:"facultyName"},{label:"Activity",key:"title",sortKey:"title"},{label:"Category",key:"category"},{label:"Date",key:"activity_date",sortKey:"activity_date"},{label:"Organizer",key:"organizer"},{label:"Status",key:"status",render:r=>badge(r.status)}],filename:"campusx-faculty-activities.csv"});main.querySelector("[data-add-activity]")?.addEventListener("click",()=>{const fields=[selectField("faculty_id","Faculty",data.faculty,r=>r.id,r=>`${r.faculty_id} — ${fullName(r)}`),`<label>Category<select name="category">${["Workshop","Conference","Research Publication","FDP","Seminar","Guest Lecture","Certification","Industry Interaction"].map(x=>`<option>${x}</option>`).join("")}</select></label>`,inputField("title","Title","text","required"),inputField("organizer","Organizer","text"),inputField("activity_date","Date","date","required"),`<label>Status<select name="status">${optionList(["PLANNED","ONGOING","COMPLETED","CANCELLED"],"PLANNED")}</select></label>`];formModal("Add Faculty Activity",fields,async v=>{if(!v.faculty_id||!v.title.trim()||!v.activity_date)throw new Error("Faculty, title and date are required.");if(live)return service.createActivity(v);data.activities.unshift({id:"demo-ac-"+Date.now(),...v});return {ok:true};});});}

function renderAnnouncements(type){const isNotice=type==="notices";const rows=isNotice?[{id:"no1",title:"Internal Assessment Documentation",date:"22 Sep",status:"Active",text:"Faculty members must complete assessment documentation by 25 September."},{id:"no2",title:"Exam Duty Allocation",date:"21 Sep",status:"Active",text:"Review assigned examination duty schedules."}]:[{id:"an1",title:"Faculty Meeting",date:"Today",status:"Published",text:"Faculty meeting scheduled at 3:30 PM in the seminar hall."},{id:"an2",title:"FDP Registration",date:"Yesterday",status:"Published",text:"Registration is open for the Applied AI faculty development programme."}];main.innerHTML=`${head(isNotice?"Faculty Notices":"Faculty Announcements",isNotice?"Operational notices for Faculty Administration.":"Academic and administrative announcements for faculty.")}<section class="card"><div class="notice-list">${rows.map(r=>`<div class="notice-item notice-info"><span>${icon(isNotice?"notice":"message")}</span><div><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.text)} · ${escapeHtml(r.date)}</small></div></div>`).join("")}</div></section>`;}
function renderNotifications(){main.innerHTML=`${head("Faculty Notifications","Operational alerts from attendance, timetable, workload and request workflows.",`<button class="btn btn-secondary" type="button" data-mark-all>Mark all read</button>`)}<section class="card" data-notification-list>${data.notifications.map(n=>`<div class="faculty-notification-row ${n.unread?"unread":""}" data-notification="${n.id}"><span class="activity-icon">${icon("bell")}</span><div><strong>${escapeHtml(n.title)}</strong><p>${escapeHtml(n.text)}</p></div><time>${escapeHtml(n.time)}</time><button class="table-action" type="button" data-mark-read="${n.id}">${n.unread?"Mark read":"Read"}</button></div>`).join("")}</section>`;main.addEventListener("click",e=>{const b=e.target.closest("[data-mark-read]");if(b){const n=data.notifications.find(x=>x.id===b.dataset.markRead);if(n)n.unread=false;renderNotifications();}} ,{once:true});main.querySelector("[data-mark-all]")?.addEventListener("click",()=>{data.notifications.forEach(n=>n.unread=false);renderNotifications();});}

function renderReports(kind="faculty"){const rows=data.faculty.map(f=>{const w=workloadFor(f.id);return {id:f.id,name:fullName(f),department:departmentFor(f),designation:f.designation,qualification:f.qualification,experience:n(f.experience),attendance:attendanceRate(f.id),workload:w.total,workloadStatus:workloadStatus(w.total),status:f.status}});const byDept=[...new Set(rows.map(r=>r.department))].map(d=>({label:d,value:rows.filter(r=>r.department===d).length}));const title=kind==="workload"?"Workload Report":kind==="attendance"?"Attendance Report":"Faculty Reports";const summary=kind==="workload"?[stat("Average Workload",`${(rows.reduce((s,r)=>s+r.workload,0)/Math.max(1,rows.length)).toFixed(1)}h`),stat("Low",rows.filter(r=>r.workloadStatus==="Low").length),stat("Normal",rows.filter(r=>r.workloadStatus==="Normal").length),stat("High",rows.filter(r=>r.workloadStatus==="High").length),stat("Overloaded",rows.filter(r=>r.workloadStatus==="Overloaded").length)]:kind==="attendance"?[stat("Average Attendance",`${Math.round(rows.reduce((s,r)=>s+r.attendance,0)/Math.max(1,rows.length))}%`),stat("Good",rows.filter(r=>r.attendance>=90).length),stat("Attention",rows.filter(r=>r.attendance>=80&&r.attendance<90).length),stat("Critical",rows.filter(r=>r.attendance<80).length),stat("Departments",byDept.length)]:[stat("Total Faculty",rows.length),stat("Active",rows.filter(r=>r.status==="ACTIVE").length),stat("On Leave",rows.filter(r=>r.status==="ON_LEAVE").length),stat("Departments",byDept.length),stat("Average Experience",`${(rows.reduce((s,r)=>s+r.experience,0)/Math.max(1,rows.length)).toFixed(1)} yrs`)];main.innerHTML=`${head(title,"Operational Faculty Administration report generated from the current CampusX dataset.")}<section class="faculty-kpi-row">${summary.join("")}</section><section class="faculty-report-grid"><article class="card faculty-chart-card"><h2>Department Distribution</h2><div class="faculty-progress-list">${byDept.map(x=>`<div class="faculty-progress-row"><span>${escapeHtml(x.label)}</span><i style="--bar:${rows.length?x.value/rows.length*100:0}%"></i><strong>${x.value}</strong></div>`).join("")}</div></article><article class="card faculty-chart-card"><h2>${kind==="attendance"?"Attendance Bands":"Workload Bands"}</h2><div class="faculty-progress-list">${(kind==="attendance"?[{label:"90%+",value:rows.filter(r=>r.attendance>=90).length},{label:"80–89%",value:rows.filter(r=>r.attendance>=80&&r.attendance<90).length},{label:"Below 80%",value:rows.filter(r=>r.attendance<80).length}]:[{label:"Low",value:rows.filter(r=>r.workloadStatus==="Low").length},{label:"Normal",value:rows.filter(r=>r.workloadStatus==="Normal").length},{label:"High",value:rows.filter(r=>r.workloadStatus==="High").length},{label:"Overloaded",value:rows.filter(r=>r.workloadStatus==="Overloaded").length}]).map(x=>`<div class="faculty-progress-row"><span>${x.label}</span><i style="--bar:${rows.length?x.value/rows.length*100:0}%"></i><strong>${x.value}</strong></div>`).join("")}</div></article><article class="card faculty-chart-card"><h2>Qualification Distribution</h2><div class="faculty-progress-list">${[...new Set(rows.map(r=>r.qualification||"Not specified"))].map(q=>{const v=rows.filter(r=>(r.qualification||"Not specified")===q).length;return `<div class="faculty-progress-row"><span>${escapeHtml(q)}</span><i style="--bar:${rows.length?v/rows.length*100:0}%"></i><strong>${v}</strong></div>`}).join("")}</div></article></section><div id="module-table"></div>`;mountTable({rows,searchFields:["name","department","designation","qualification"],columns:[{label:"Faculty",key:"name",sortKey:"name"},{label:"Department",key:"department",sortKey:"department"},{label:"Designation",key:"designation"},{label:"Qualification",key:"qualification"},{label:"Experience",key:"experience",sortKey:"experience"},{label:"Attendance",key:"attendance",sortKey:"attendance",render:r=>`${r.attendance}%`},{label:"Workload",key:"workload",sortKey:"workload",render:r=>`${r.workload}h`},{label:"Status",key:"status",render:r=>badge(r.status)}],filename:`campusx-${kind}-report.csv`});}
function renderAnalytics(){const rows=data.faculty.map(f=>({f,department:departmentFor(f),attendance:attendanceRate(f.id),workload:workloadFor(f.id).total}));const cards=[["Faculty Strength",data.faculty.length],["Departments",new Set(rows.map(r=>r.department)).size],["Avg Attendance",`${Math.round(rows.reduce((s,r)=>s+r.attendance,0)/Math.max(1,rows.length))}%`],["Avg Workload",`${(rows.reduce((s,r)=>s+r.workload,0)/Math.max(1,rows.length)).toFixed(1)}h`],["Leave Requests",data.leaveRequests.length]];main.innerHTML=`${head("Faculty Analytics","Operational analytics across faculty strength, workload, attendance, leave and assignments.")}<section class="faculty-kpi-row">${cards.map(x=>stat(x[0],x[1])).join("")}</section><section class="faculty-report-grid"><article class="card faculty-chart-card"><h2>Department Distribution</h2>${analyticsBars([...new Set(rows.map(r=>r.department))].map(d=>[d,rows.filter(r=>r.department===d).length]),rows.length)}</article><article class="card faculty-chart-card"><h2>Designation Distribution</h2>${analyticsBars([...new Set(rows.map(r=>r.f.designation))].map(d=>[d,rows.filter(r=>r.f.designation===d).length]),rows.length)}</article><article class="card faculty-chart-card"><h2>Qualification Distribution</h2>${analyticsBars([...new Set(rows.map(r=>r.f.qualification||"Unknown"))].map(d=>[d,rows.filter(r=>(r.f.qualification||"Unknown")===d).length]),rows.length)}</article><article class="card faculty-chart-card"><h2>Attendance Trends</h2>${analyticsBars([["Good 90%+",rows.filter(r=>r.attendance>=90).length],["Attention 80–89%",rows.filter(r=>r.attendance>=80&&r.attendance<90).length],["Critical <80%",rows.filter(r=>r.attendance<80).length]],rows.length)}</article><article class="card faculty-chart-card"><h2>Workload Trends</h2>${analyticsBars([["Low",rows.filter(r=>workloadStatus(r.workload)==="Low").length],["Normal",rows.filter(r=>workloadStatus(r.workload)==="Normal").length],["High",rows.filter(r=>workloadStatus(r.workload)==="High").length],["Overloaded",rows.filter(r=>workloadStatus(r.workload)==="Overloaded").length]],rows.length)}</article><article class="card faculty-chart-card"><h2>Assignments</h2>${analyticsBars([["Subjects",data.subjectAssignments.length],["Classes",data.classAssignments.length],["Schedule Entries",data.schedule.length],["Resources",data.resources.length]],Math.max(1,data.subjectAssignments.length+data.classAssignments.length))}</article></section>`;}
function analyticsBars(items,total){return `<div class="faculty-progress-list">${items.map(([l,v])=>`<div class="faculty-progress-row"><span>${escapeHtml(l)}</span><i style="--bar:${Math.min(100,(n(v)/Math.max(1,total))*100)}%"></i><strong>${escapeHtml(v)}</strong></div>`).join("")}</div>`}
function renderAdminAccount(type){const title=type==="settings"?"Faculty Admin Settings":"Faculty Admin Profile";main.innerHTML=`${head(title,type==="settings"?"Interface and notification preferences for the Faculty Administration account.":"Faculty Administration account profile.")}<section class="card">${type==="settings"?`<div class="form-grid"><label class="form-check"><input type="checkbox" checked> Workload alerts</label><label class="form-check"><input type="checkbox" checked> Attendance alerts</label><label class="form-check"><input type="checkbox" checked> Leave request alerts</label><label class="form-check"><input type="checkbox"> Reduce animation</label></div>`:`<div class="faculty-detail-grid">${[["Role","FACULTY_ADMIN"],["Portal","Faculty Administration"],["Account Status","Active"],["Authentication","Supabase Auth"]].map(x=>`<div class="faculty-detail-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("")}</div>`}</section>`;}

function render(){document.body.classList.add("faculty-page");switch(page){case"dashboard":renderDashboard();break;case"faculty":case"faculty-profiles":renderFacultyDirectory();break;case"add-faculty":renderLegacyAdd();break;case"faculty-profile":renderProfile();break;case"departments":renderDepartments();break;case"subject-assignments":case"subjects":renderAssignments("subject");break;case"class-assignments":case"classes":renderAssignments("class");break;case"workload":renderWorkload();break;case"lecture-schedule":renderSchedule(false);break;case"timetable":renderSchedule(true);break;case"attendance":renderAttendance();break;case"leave-requests":case"leave":renderLeave();break;case"requests":renderRequests();break;case"resources":renderResources();break;case"documents":renderDocuments();break;case"academic-responsibilities":renderResponsibilities();break;case"activities":renderActivities();break;case"announcements":renderAnnouncements("announcements");break;case"notices":renderAnnouncements("notices");break;case"notifications":renderNotifications();break;case"faculty-reports":case"reports":renderReports("faculty");break;case"workload-reports":renderReports("workload");break;case"attendance-reports":renderReports("attendance");break;case"analytics":renderAnalytics();break;case"profile":renderAdminAccount("profile");break;case"settings":renderAdminAccount("settings");break;default:renderDashboard();}}
